  pal: { "a": "#5a3c12", "b": "#735935", "c": "#e1ba65", "d": "#dcae4a", "e": "#33657a", "f": "#0f4a63", "g": "#17698a", "h": "#3a7f9b", "i": "#45a6c8", "j": "#2596be", "k": "#b8862b", "l": "#f6dc8c", "m": "#3a2a1c" },
