/**
 * The battle stage: the gallery seen at battle angle. A wall with frames out
 * of focus, the parquet running away in perspective, a spotlight on the
 * opponent's rug and dust turning in its beam. Integer fillRects only, so it
 * stays crisp at any integer scale. Complete at t = 0; t only drifts the dust.
 */
export function drawBattleBackdrop(g: CanvasRenderingContext2D, t: number): void {
  const f = (c: string, x: number, y: number, w: number, h: number): void => {
    g.fillStyle = c;
    g.fillRect(x, y, w, h);
  };
  const lerp = (a: number, b: number, k: number): number => a + (b - a) * k;
  const rgb = (a: number[], b: number[], k: number): string =>
    "rgb(" + Math.round(lerp((a[0] ?? 0), (b[0] ?? 0), k)) + "," + Math.round(lerp((a[1] ?? 0), (b[1] ?? 0), k)) + "," + Math.round(lerp((a[2] ?? 0), (b[2] ?? 0), k)) + ")";

  // ---- wall
  const WALL_TOP = [226, 219, 207], WALL_LOW = [245, 241, 234];
  for (let y = 0; y < 62; y++) f(rgb(WALL_TOP, WALL_LOW, y / 61), 0, y, 256, 1);
  // cornice and picture rail
  f("#3b3236", 0, 0, 256, 2);
  f("#c9bfae", 0, 2, 256, 1);
  f("#f6f2ea", 0, 3, 256, 2);
  for (let x = 0; x < 256; x += 6) f("#d3c9b8", x, 5, 3, 2);
  f("#d6ccbb", 0, 7, 256, 1);
  f("#f6dc8c", 0, 9, 256, 1);
  f("#b8862b", 0, 10, 256, 1);
  f("#d4cabb", 0, 11, 256, 1);

  // ---- frames, out of focus: soft halo, gilt band, painting as soft blocks
  const frame = (x: number, y: number, w: number, h: number, blocks: [string, number, number, number, number][]): void => {
    f("rgba(58,42,16,0.10)", x + 2, y + 3, w, h);
    f("rgba(214,170,80,0.35)", x - 2, y - 2, w + 4, h + 4);
    f("rgba(214,170,80,0.55)", x - 1, y - 1, w + 2, h + 2);
    f("#c99a3c", x, y, w, h);
    f("#dcb258", x + 1, y + 1, w - 2, h - 2);
    f("#a8792a", x + 3, y + 3, w - 6, h - 6);
    for (const [c, bx, by, bw, bh] of blocks) {
      f(c, x + 4 + bx, y + 4 + by, bw, bh);
    }
    f("rgba(255,255,255,0.10)", x + 4, y + 4, w - 8, 3);
  };
  // werc: night sky, grey moon, cyan glow
  frame(14, 18, 52, 36, [["#141a3a", 0, 0, 44, 28], ["#1e2850", 0, 6, 44, 8], ["#8e8e98", 0, 18, 44, 10], ["#a0a0aa", 0, 17, 44, 2], ["#6fc4de", 30, 9, 5, 10], ["#4a90a8", 28, 10, 2, 8], ["#d0d0d6", 12, 14, 14, 5]]);
  // bot: navy with cyan candles
  frame(96, 24, 32, 26, [["#0e1826", 0, 0, 24, 18], ["#3f8fb0", 3, 9, 3, 6], ["#6fc4de", 9, 6, 3, 6], ["#3f8fb0", 15, 4, 3, 5], ["#6fc4de", 20, 1, 3, 6]]);
  // wave: sky over sea, behind the opponent
  frame(166, 16, 64, 40, [["#b5dff0", 0, 0, 56, 16], ["#2a77b5", 0, 16, 56, 16], ["#5aa6d6", 0, 16, 56, 3], ["#e8a030", 22, 12, 8, 8], ["#1f5f98", 0, 26, 56, 6]]);
  // small campus study at the far right edge
  frame(242, 22, 22, 28, [["#a6cf86", 0, 0, 14, 20], ["#c9744a", 2, 3, 5, 5], ["#2596be", 7, 8, 4, 5]]);

  // sconces with warm wash
  const sconce = (x: number): void => {
    f("rgba(255,223,154,0.12)", x - 10, 8, 22, 40);
    f("rgba(255,223,154,0.14)", x - 6, 10, 14, 26);
    f("#fff4d6", x - 3, 14, 8, 4);
    f("#dcae4a", x - 3, 18, 8, 1);
    f("#b8862b", x, 19, 2, 4);
  };
  sconce(82);
  sconce(146);

  // ---- dado: chair rail, teal panels, skirting
  f("#f6dc8c", 0, 66, 256, 1);
  f("#8a6322", 0, 67, 256, 1);
  f("#2596be", 0, 68, 256, 1);
  f("#17698a", 0, 69, 256, 10);
  for (let x = 4; x < 256; x += 36) {
    f("#2596be", x, 71, 30, 5);
    f("#6fc4de", x, 71, 30, 1);
    f("#0f4a63", x + 29, 71, 1, 5);
    f("#0f4a63", x, 76, 30, 1);
  }
  f("#0f4a63", 0, 78, 256, 1);
  f("#5a4a40", 0, 79, 256, 1);
  f("#4a3a32", 0, 80, 256, 2);
  f("#2a201c", 0, 82, 256, 1);

  // ---- floor in perspective: planks run toward us, fanning from a vanishing point
  const VP = 128, HZ = 20, Y0 = 83, PW = 0.14;
  const BACK = [196, 145, 88], FRONT = [222, 176, 118];
  const SHIFT = [0, -9, 6, -4, 10, -12];
  let prevZ: Record<number, number> = {};
  for (let y = Y0; y < 192; y++) {
    const d = y - HZ, k = (y - Y0) / (191 - Y0);
    const base = [lerp((BACK[0] ?? 0), (FRONT[0] ?? 0), k), lerp((BACK[1] ?? 0), (FRONT[1] ?? 0), k), lerp((BACK[2] ?? 0), (FRONT[2] ?? 0), k)];
    const w = PW * d;
    const k0 = Math.floor(-VP / w) - 1, k1 = Math.ceil((256 - VP) / w) + 1;
    const z = 3000 / d;
    const zs: Record<number, number> = {};
    for (let p = k0; p <= k1; p++) {
      const x0 = Math.round(VP + p * w), x1 = Math.round(VP + (p + 1) * w);
      if (x1 <= 0 || x0 >= 256) continue;
      const sh = SHIFT[((p % 6) + 6) % 6] ?? 0;
      const tone = "rgb(" + Math.round((base[0] ?? 0) + sh) + "," + Math.round((base[1] ?? 0) + sh * 0.8) + "," + Math.round((base[2] ?? 0) + sh * 0.6) + ")";
      const joint = Math.floor((z + ((p * 23) % 40 + 40) % 40) / 40);
      const isJoint = prevZ[p] !== undefined && prevZ[p] !== joint;
      zs[p] = joint;
      f(isJoint ? "#a8784a" : tone, x0, y, x1 - x0, 1);
      f("rgba(150,100,55,0.7)", x0, y, 1, 1);
    }
    prevZ = zs;
  }
  // wall contact shadow on the floor
  f("rgba(58,36,16,0.34)", 0, 83, 256, 2);
  f("rgba(58,36,16,0.18)", 0, 85, 256, 2);
  f("rgba(58,36,16,0.08)", 0, 87, 256, 3);
  // polished reflections of the frames and dado
  f("rgba(23,105,138,0.10)", 0, 90, 256, 6);
  f("rgba(220,178,88,0.12)", 14, 90, 52, 10);
  f("rgba(220,178,88,0.10)", 96, 90, 32, 8);
  f("rgba(220,178,88,0.12)", 166, 90, 64, 10);

  // ---- spotlight cone from above onto the opponent's rug (centre x 188)
  for (let y = 0; y < 100; y++) {
    const k = y / 99;
    const cx = Math.round(lerp(204, 188, k));
    const hw = Math.round(lerp(10, 54, k));
    f("rgba(255,244,214,0.09)", cx - hw, y, hw * 2, 1);
    f("rgba(255,244,214,0.07)", cx - Math.round(hw * 0.6), y, Math.round(hw * 1.2), 1);
  }
  // pools of light on the floor
  const pool = (cx: number, cy: number, rx: number, ry: number, a: number): void => {
    for (let j = -ry; j <= ry; j++) {
      const w = Math.round(rx * Math.sqrt(1 - (j * j) / (ry * ry)));
      f("rgba(255,240,200," + a + ")", cx - w, cy + j, w * 2, 1);
    }
  };
  pool(188, 101, 72, 17, 0.12);
  pool(188, 101, 52, 12, 0.12);
  pool(188, 101, 32, 8, 0.1);
  pool(64, 174, 84, 18, 0.07);
  pool(64, 174, 56, 12, 0.06);

  // ---- vignette
  for (let i = 0; i < 6; i++) {
    const a = 0.07 * (6 - i) / 6;
    f("rgba(40,24,10," + a.toFixed(3) + ")", 0, 186 - i * 4, 256, 4);
    f("rgba(40,24,10," + a.toFixed(3) + ")", i * 3, 0, 3, 192);
    f("rgba(40,24,10," + a.toFixed(3) + ")", 253 - i * 3, 0, 3, 192);
  }

  // ---- dust turning in the beam
  for (let i = 0; i < 22; i++) {
    const span = 96;
    const y = Math.floor((i * 41 + t * (3 + (i % 3))) % span) + 2;
    const k = y / 99;
    const cx = lerp(204, 188, k), hw = lerp(10, 54, k) * 0.8;
    const x = Math.round(cx + Math.sin(i * 2.3 + t * 0.6) * hw * ((i % 5) / 5 + 0.2));
    const a = 0.35 + 0.35 * Math.abs(Math.sin(i * 1.7 + t * 1.3));
    f("rgba(255,250,228," + a.toFixed(2) + ")", x, Math.round(y), i % 4 === 0 ? 2 : 1, 1);
  }
}
